package com.example.app10.application.service; import com.example.app10.domain.entity.Metric; import com.example.app10.infrastructure.repository.MetricRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class MetricService { private final MetricRepository repository; public MetricService(MetricRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Metric> list() { return repository.findAll(); } @Transactional public Metric create(Metric e) { return repository.save(e); } }
